import{z as i,x as n,o as B,c as m,q as t,j as o,D as e,d as l,s as A,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"分布外的奖励行为","description":"","frontmatter":{"title":"分布外的奖励行为","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-ood-behavior.md","filePath":"llm/rm-ood-behavior.md","lastUpdated":1791413859000}'),d={name:"llm/rm-ood-behavior.md"};function D(h,E,C,p,u,f){const r=n("Mermaid");return B(),m("div",null,[E[2]||(E[2]=t('<h1 id="分布外的奖励行为" tabindex="-1">分布外的奖励行为 <a class="header-anchor" href="#分布外的奖励行为" aria-label="Permalink to &quot;分布外的奖励行为&quot;">​</a></h1><div class="epigraph"><p>奖励模型只在比较数据的邻域内有定义；策略一旦走出那片邻域，分数仍会输出，只是不再对应任何人的判断。</p><footer>—— 过优化曲线见 Gao、Schulman、Hilton 2022；集成不确定性作为 OOD 信号见 Coste 等 2023</footer></div><p><a href="/llm/rm-style-bias">上一课</a>把表面特征的偏置清单拉完，都是<strong>分布内</strong>的病：数据里有的捷径被利用。本课转向分布外：RL 把策略推出比较数据的支撑之后，RM 的分数行为没有任何保证。<a href="/llm/rm-overoptimization">RM 过优化与 Goodhart</a> 已把宏观曲线（代理奖励涨、金标先升后降）讲过，<a href="/llm/rm-ensembles">RM 集成与不确定性</a>给了不确定性的定义；本课写工程侧：怎么监测策略正在走出支撑、走出之后拿什么兜底。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BT 损失只在训练对上约束 \\(r\\)：它要求 \\(r_w \\gt r_l\\) 在样本处成立，样本之间的曲面形状由归纳偏置自由决定。PPO 每步把策略向高分区域推，高分区域先是「数据里真正更好的区域」，随后是「RM 外推想象出来的更好区域」——两者在支撑边缘开始分叉，这正是过优化曲线拐点的微观机制。危险在于分叉不可见：代理分数照常上涨，唯一知道真相的金标（人、更大 RM、任务指标）不在训练回路里。不这么做会错在哪：训练到第 300 步才发现回答开始出现奇怪的句子结构——那是策略找到了 RM 外推的高分谷，此时回滚窗口已过。</p><p><span class="marginnote">直觉类比：RM 像一个只背过市区地图的导航。在市区里（训练数据的邻域）它指路很准；一旦车开出地图边缘，它不会说「我不知道」，而是继续自信地报路——那些路指向地图上不存在的地方。策略拿高分当路标往前开，开进的正是这种「外推想象出来的好地方」。</span></p><h3 id="监测-三个支撑代理" tabindex="-1">监测：三个支撑代理 <a class="header-anchor" href="#监测-三个支撑代理" aria-label="Permalink to &quot;监测：三个支撑代理&quot;">​</a></h3><p>支撑不可观测，只能用代理。其一，KL 距离：策略与参考策略的逐域 KL 是「走多远」的度量，KL 球本来就是支撑边界的工程近似，<a href="/llm/ppo-kl-value">KL 惩罚</a>的系数因此不只是稳定性旋钮，也是外推风险旋钮。其二，集成分歧：多个独立 RM 对同一条完成打分的标准差 \\(\\hat\\sigma\\)（<a href="/llm/rm-ensembles">RM 集成</a>的产出），分歧在支撑内低、支撑外暴涨，是成本最低的内窥镜。其三，分数分布漂移：训练中 \\(r(x,y)\\) 的均值与尾部随步数的移动，配合定期小规模人评抽检——每 \\(n\\) 步把当期最高分样本送人判，人判与 RM 的一致率是唯一不经过代理的金标。</p>',8)),(B(),o(s,null,{default:e(()=>[A(r,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20PPO%5B%22%E7%AD%96%E7%95%A5%E6%9B%B4%E6%96%B0%22%5D%20--%3E%20KL%5B%22%E9%80%90%E5%9F%9F%20KL%20%E7%9B%91%E6%B5%8B%22%5D%0A%20%20PPO%20--%3E%20DISP%5B%22%E9%9B%86%E6%88%90%E5%88%86%E6%AD%A7%20%CF%83%CC%82%20%E7%9B%91%E6%B5%8B%22%5D%0A%20%20PPO%20--%3E%20DRIFT%5B%22%E5%88%86%E6%95%B0%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%E7%9B%91%E6%B5%8B%22%5D%0A%20%20KL%20--%3E%7C%E8%B6%85%E5%9F%9F%E9%98%88%E5%80%BC%7C%20THROTTLE%5B%22%E6%94%B6%E7%BC%A9%E6%AD%A5%E9%95%BF%E6%88%96%E5%81%9C%E8%AE%AD%22%5D%0A%20%20DISP%20--%3E%7C%CF%83%CC%82%20%E6%8A%AC%E5%8D%87%7C%20THROTTLE%0A%20%20DRIFT%20--%3E%7C%E5%B0%BE%E9%83%A8%E5%BC%82%E5%B8%B8%7C%20HUMAN%5B%22%E4%BA%BA%E8%AF%84%E6%8A%BD%E6%A3%80%22%5D%0A%20%20HUMAN%20--%3E%7C%E4%B8%80%E8%87%B4%E7%8E%87%E4%B8%8B%E6%BB%91%7C%20ROLLBACK%5B%22%E5%9B%9E%E6%BB%9A%E5%88%B0%E4%B8%8A%E4%B8%80%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20THROTTLE%20--%3E%20RE%5B%22%E9%87%8D%E9%87%87%E6%AF%94%E8%BE%83%E5%AF%B9%E8%A1%A5%E6%95%B0%E6%8D%AE%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>工程动作按发现顺序接续。预防：KL 系数按域设阈值，超阈收缩学习率或停训——把「走多远」钉在支撑大概率尚存的范围内。检测：把 \\(\\hat\\sigma\\) 写进训练日志，与奖励同图监控；\\(\\hat\\sigma\\) 的分位数（如 P90）比均值敏感，先抬头。兜底：分歧大的样本不要扔，它们是下一批标注的最优原料（工程单元的主动采集课展开），把外推区域重新拉回有数据的区域。可验证域另有一条硬兜底：数学与代码切到<a href="/llm/verifiable-reward">可验证奖励</a>或混合加权，验证器不外推——它只判对错，RM 负责的「好不好」再交还给有数据的区域。</p><p><span class="marginnote">术语翻译：KL（Kullback-Leibler 散度）衡量两个概率分布「差多远」，为 0 表示完全相同，越大越不像。这里算的是「当前策略和参考策略生成文本的概率分布」之间的距离——KL 涨得快，就说明策略已经离开出发地很远，外推风险随之上升。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么集成 \\(\\hat\\sigma\\) 能当 OOD 信号：各成员在训练分布上被同一批对约束，预测被拉齐；离开分布，约束消失，各自归纳偏置起作用，预测发散。Coste 等 2023 把这个分歧用进 RL：在不确定处收缩优势，等价于把策略软性摁在支撑附近。但要明白它量的是什么：\\(\\hat\\sigma\\) 是<strong>这族 RM 内部</strong>的一致性，成员同源（同初始化、同数据）时分歧会系统性低估真实的不确定性——Eisenstein 等 2023 的批评在工程单元的公平比较课展开。为什么 KL 只是近似：KL 小不等于在支撑内——策略可以留在 KL 球内但落在数据密度的洞里；KL 是必要条件不是充分条件，所以三个代理要同时看。</p><p><span class="marginnote">Gao 等 2022 的标度律给监测提供了预期管理：RM 越大、数据越多，拐点越晚但不消失。日志里应同时记录优化步数与代理奖励积分，对照标度律预估「还剩多少安全余量」。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课的方法都不能消灭外推，只能推迟与发现。人评抽检的时延与样本量决定它只能抓宏观趋势，抓不住单条异常；分歧信号本身可以被策略利用——策略若学会避开分歧大的区域，\\(\\hat\\sigma\\) 会回落而外推照旧，这是把监测量变成优化目标后的标准副作用（Goodhart 的递归）。支撑的几何也没有想象中清晰：高维里「邻域」由 RM 的表征决定，两个输入在 token 空间近、在表征空间远（或反之）都常见，这正是下一课要把奖励当成随机变量、从方差角度重看稳定性的原因。</p>',8)),(B(),o(s,null,{default:e(()=>[A(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E8%AE%AD%E7%BB%83%E5%88%86%E5%B8%83%E5%86%85%EF%BC%9A%E5%90%8C%E4%B8%80%E6%89%B9%E6%AF%94%E8%BE%83%E5%AF%B9%E7%BA%A6%E6%9D%9F%E6%89%80%E6%9C%89%E6%88%90%E5%91%98%22%5D%20--%3E%20AL%5B%22%E9%A2%84%E6%B5%8B%E8%A2%AB%E6%8B%89%E9%BD%90%EF%BC%8C%CF%83%CC%82%20%E4%BD%8E%22%5D%0A%20%20OUT%5B%22%E7%AD%96%E7%95%A5%E8%B5%B0%E5%87%BA%E6%94%AF%E6%92%91%EF%BC%9A%E7%BA%A6%E6%9D%9F%E6%B6%88%E5%A4%B1%22%5D%20--%3E%20OWN%5B%22%E5%90%84%E6%88%90%E5%91%98%E7%9A%84%E5%BD%92%E7%BA%B3%E5%81%8F%E7%BD%AE%E6%8E%A5%E7%AE%A1%22%5D%0A%20%20OWN%20--%3E%20DIV%5B%22%E9%A2%84%E6%B5%8B%E5%8F%91%E6%95%A3%EF%BC%8C%CF%83%CC%82%20%E6%9A%B4%E6%B6%A8%22%5D%0A%20%20DIV%20--%3E%20SIG%5B%22%E9%9B%86%E6%88%90%E5%88%86%E6%AD%A7%20%E2%89%88%20OOD%20%E5%86%85%E7%AA%A5%E9%95%9C%22%5D%0A%20%20HOMO%5B%22%E6%88%90%E5%91%98%E5%90%8C%E6%BA%90%EF%BC%9A%E5%90%8C%E5%88%9D%E5%A7%8B%E5%8C%96%E3%80%81%E5%90%8C%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20LOW%5B%22%E5%88%86%E6%AD%A7%E7%B3%BB%E7%BB%9F%E6%80%A7%E4%BD%8E%E4%BC%B0%E7%9C%9F%E5%AE%9E%E4%B8%8D%E7%A1%AE%E5%AE%9A%E6%80%A7%22%5D%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"为什么人评抽检不可省：三个代理都是「间接测量」，只有把当期最高分样本拿给人判，才有一条不经过 RM 自身的金标线。抽检就像财务审计——平时的仪表盘再正常，也要定期抽几笔账对原件；一致率下滑往往比 σ̂ 抬升更晚但更确凿。")],-1)),E[5]||(E[5]=a("h2",{id:"小结",tabindex:"-1"},[l("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[6]||(E[6]=a("ul",null,[a("li",null,"BT 损失只在训练对邻域约束 \\(r\\)；OOD 处分数由归纳偏置决定，外推即过优化的微观机制。"),a("li",null,"三个支撑代理：逐域 KL、集成分歧 \\(\\hat\\sigma\\)、分数漂移加人评抽检，同时看，缺一不可。"),a("li",null,"KL 是必要非充分条件；\\(\\hat\\sigma\\) 受成员同源限制，会低估真实不确定性。"),a("li",null,"可验证域用验证器兜底；分歧大的样本留作下一批标注原料。"),a("li",null,"出处：Gao、Schulman、Hilton 2022；Coste 等 2023；Eisenstein 等 2023。")],-1))])}const L=i(d,[["render",D]]);export{F as __pageData,L as default};
